import{_ as l,o as e,c as i,ae as r}from"./chunks/framework.RRduUuAx.js";const c=JSON.parse('{"title":"환불 안내","description":"","frontmatter":{},"headers":[],"relativePath":"v1/ko/guide/10-bill-refund-guide.md","filePath":"v1/ko/guide/10-bill-refund-guide.md"}'),t={name:"v1/ko/guide/10-bill-refund-guide.md"};function o(n,a,d,h,u,s){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="환불-안내" tabindex="-1">환불 안내 <a class="header-anchor" href="#환불-안내" aria-label="Permalink to &quot;환불 안내&quot;">​</a></h1><h2 id="_1-어떤-기능인가요" tabindex="-1">1. 어떤 기능인가요? <a class="header-anchor" href="#_1-어떤-기능인가요" aria-label="Permalink to &quot;1. 어떤 기능인가요?&quot;">​</a></h2><p>‘환불’은 거래가 환불되었을 때의 자금 흐름을 기록하고, 통계에서 해당 금액 영향이 자동으로 상쇄되도록 하기 위한 기능입니다.</p><p>Koala는 원거래를 기준으로 ‘음수 금액’의 환불 기록을 추가로 생성합니다.</p><ul><li>원거래가 지출이면: 환불 기록도 ‘지출’이지만 금액이 음수로 저장되어 원 지출을 상쇄합니다</li><li>원거래가 수입이면: 환불 기록도 ‘수입’이지만 금액이 음수로 저장되어 원 수입을 상쇄합니다</li></ul><p>또한 환불 기록에는 자동으로 ‘환불’ 태그가 붙어, 나중에 필터링/확인이 쉽습니다.</p><h2 id="_2-이런-경우에-유용해요" tabindex="-1">2. 이런 경우에 유용해요 <a class="header-anchor" href="#_2-이런-경우에-유용해요" aria-label="Permalink to &quot;2. 이런 경우에 유용해요&quot;">​</a></h2><ul><li>구매 환불/반품 환불</li><li>부분 환불</li><li>수입 회수(예: 이체 취소, 입금 반송)</li></ul><h2 id="_3-사용-방법" tabindex="-1">3. 사용 방법 <a class="header-anchor" href="#_3-사용-방법" aria-label="Permalink to &quot;3. 사용 방법&quot;">​</a></h2><ol><li>거래 목록에서 환불할 거래를 찾습니다</li><li>해당 거래를 왼쪽으로 스와이프한 뒤 <strong>환불</strong>을 선택합니다</li><li>환불 화면에서 설정합니다: <ul><li>금액: 기본값은 원거래 금액이며, 부분 환불이면 변경할 수 있습니다</li><li>날짜: 기본값은 오늘이며, 필요 시 실제 환불 날짜로 변경합니다</li><li>태그: 원거래 태그를 유지하고 <strong>환불</strong> 태그가 자동으로 추가됩니다</li><li>메모: 선택 사항</li></ul></li><li><strong>확인/완료</strong>를 눌러 저장합니다</li></ol><p>저장하면 목록에 환불 기록이 추가되어 해당 금액 영향이 상쇄됩니다.</p><h2 id="_4-규칙-및-주의사항" tabindex="-1">4. 규칙 및 주의사항 <a class="header-anchor" href="#_4-규칙-및-주의사항" aria-label="Permalink to &quot;4. 규칙 및 주의사항&quot;">​</a></h2><ul><li>환불 금액은 ‘실제로 돌려받은 금액’을 입력하면 됩니다. 마이너스 기호를 직접 입력할 필요는 없습니다.</li><li>지출 환불/수입 환불 모두 ‘음수 금액’으로 기록되므로 통계에서 자동으로 상쇄됩니다.</li><li>여러 번 환불도 가능합니다. 같은 거래가 여러 번에 나뉘어 환불되면, 환불할 때마다 환불 기록이 1건씩 생성됩니다.</li><li>환불 기록을 삭제하면 상쇄 효과도 사라져 통계가 환불 전 상태로 돌아갑니다.</li></ul><h2 id="_5-자주-묻는-질문" tabindex="-1">5. 자주 묻는 질문 <a class="header-anchor" href="#_5-자주-묻는-질문" aria-label="Permalink to &quot;5. 자주 묻는 질문&quot;">​</a></h2><h3 id="q1-부분-환불은-어떻게-기록하나요" tabindex="-1">Q1. 부분 환불은 어떻게 기록하나요? <a class="header-anchor" href="#q1-부분-환불은-어떻게-기록하나요" aria-label="Permalink to &quot;Q1. 부분 환불은 어떻게 기록하나요?&quot;">​</a></h3><p>환불 화면에서 금액을 실제 환불 금액으로 변경하면 됩니다. 여러 번에 나눠 환불하는 것도 가능합니다.</p><h3 id="q2-환불하면-원거래가-바뀌나요" tabindex="-1">Q2. 환불하면 원거래가 바뀌나요? <a class="header-anchor" href="#q2-환불하면-원거래가-바뀌나요" aria-label="Permalink to &quot;Q2. 환불하면 원거래가 바뀌나요?&quot;">​</a></h3><p>원거래 금액은 수정되지 않습니다. 환불은 ‘환불 기록을 추가로 생성’하는 방식이라 원래 소비 기록을 보존하면서도 통계를 설명 가능하고 추적 가능하게 유지할 수 있습니다.</p><h3 id="q3-환불만-모아서-볼-수-있나요" tabindex="-1">Q3. 환불만 모아서 볼 수 있나요? <a class="header-anchor" href="#q3-환불만-모아서-볼-수-있나요" aria-label="Permalink to &quot;Q3. 환불만 모아서 볼 수 있나요?&quot;">​</a></h3><p>환불 기록에는 자동으로 ‘환불’ 태그가 붙으므로, 태그로 필터/검색해 확인할 수 있습니다.</p>',20)])])}const p=l(t,[["render",o]]);export{c as __pageData,p as default};
